mapper.update:
update chat_credit_session
set refund_state = #{refundState}, update_time = now()
where user_id = #{userId} and request_id = #{requestId}

update chat_credit_session
set refund_state = #{toState}, update_time = now()
where user_id = #{userId}
  and request_id = #{requestId}
  and deducted = 1
  and refund_state = #{fromState}

update chat_credit_session
set deduct_state = #{toState},
    deducted = CASE WHEN #{toState} = 'deducted' THEN 1 ELSE deducted END,
    update_time = now()
where user_id = #{userId}
  and request_id = #{requestId}
  and deduct_state = #{fromState}

update chat_credit_session
set deduct_state = 'deducted', deducted = 1, update_time = now()
where user_id = #{userId}
  and request_id = #{requestId}
  and deduct_state IN ('deducting', 'deducted')

update chat_credit_session
set retry_count = retry_count + 1, update_time = now()
where id = #{id}

mapper.select:
select id, user_id, request_id, deducted, deduct_amount, deduct_state, refund_state, retry_count
from chat_credit_session
where refund_state = 'pending' and retry_count < #{maxRetry}
order by create_time asc
limit #{limit}
